# owner: platform
"""Seating rows built from a list of students."""

from typing import List, Sequence

from rosterkit.models import Student

Roster = Sequence[Student]

def check_arguments(students: Roster, seats: int) -> None:
    """Reject a bad seat count or an empty list."""
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def name_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())

def split_rows(items: list, seats: int) -> list:
    """Cut the sorted students into rows of seats."""
    return [
        items[start:start + seats]
        for start in range(0, len(items), seats)
    ]

def format_row(number: int, group: list) -> str:
    names = " | ".join(
        item.display_name for item in group
    )
    return f"Row {number}: {names}"

def format_rows(rows: list) -> List[str]:
    return [
        format_row(index, group)
        for index, group in enumerate(rows, start=1)
    ]

def seat_students(students: Roster, seats: int) -> list:
    """One text line per row, sorted by last name."""
    check_arguments(students, seats)
    ordered = sorted(students, key=name_key)
    return format_rows(split_rows(ordered, seats))

after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.seating import seat_students
from rosterkit.models import Student

def make_student(last, first):
    return Student("id-" + last, last, first, "A")

ROSTER = [
    make_student("Halloway", "Juno"),
    make_student("Dunmere", "Piet"),
    make_student("Okafor", "Ada"),
]

class SeatStudentsTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_students(ROSTER, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Okafor, Ada",
            ],
        )

    def test_single_wide_row(self):
        lines = seat_students(ROSTER, 10)
        self.assertEqual(len(lines), 1)

    def test_same_last_name_uses_first_name(self):
        pair = [make_student("Reyes", "Zoe")]
        pair.append(make_student("Reyes", "Alma"))
        expected = ["Row 1: Reyes, Alma | Reyes, Zoe"]
        self.assertEqual(seat_students(pair, 2), expected)

    def test_sort_ignores_case(self):
        pair = [
            make_student("beck", "Abel"),
            make_student("Aldo", "Bert"),
        ]
        first = seat_students(pair, 1)[0]
        self.assertEqual(first, "Row 1: Aldo, Bert")

    def test_input_is_not_modified(self):
        before = list(ROSTER)
        seat_students(ROSTER, 2)
        self.assertEqual(ROSTER, before)

class SeatStudentsErrorTests(unittest.TestCase):
    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            seat_students(ROSTER, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            seat_students(ROSTER, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_students([], 4)
